import {addRoundUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, TurnUsage, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('addRoundUsage', () => {
  const ROUND: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
  const LATER: UsageMetadata = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

  it('sums each token field of two reported rounds', () => {
    expect(addRoundUsage(ROUND, LATER)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps the total when a round reports nothing', () => {
    expect(addRoundUsage(ROUND, undefined)).toEqual(ROUND);
  });

  it('starts the total from the first reported round', () => {
    expect(addRoundUsage(undefined, ROUND)).toEqual(ROUND);
  });

  it('stays undefined while no round has reported', () => {
    expect(addRoundUsage(undefined, undefined)).toBeUndefined();
  });

  it('folds every provider round of a turn into one TurnUsage', () => {
    const turn: TurnUsage | undefined = [ROUND, undefined, LATER].reduce<TurnUsage | undefined>(
      addRoundUsage,
      undefined
    );
    expect(turn).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });
});
specs/hal-engine-architecture/spec.md:340:- A round continues only when the model stopped for `tool_use`, named at least one tool, and a `ToolRegistry` is configured ([validated by: continues when the model requested a tool and a registry can run it](../../src/orchestration/orchestratorHelpers.test.ts#L11)).
specs/hal-engine-architecture/spec.md:341:- With no registry configured the loop stops, whatever the model asked for, because nothing could execute the call ([validated by: stops when no registry is configured, whatever the model asked for](../../src/orchestration/orchestratorHelpers.test.ts#L15)).
specs/hal-engine-architecture/spec.md:342:- A `tool_use` stop naming no tool stops the loop, rather than re-querying with nothing to add ([validated by: stops when the model named no tool](../../src/orchestration/orchestratorHelpers.test.ts#L19)).
specs/hal-engine-architecture/spec.md:343:- Any other stop reason ends the loop even when tool calls are pending ([validated by: stops when the model finished for a reason other than tool use](../../src/orchestration/orchestratorHelpers.test.ts#L23)).
specs/hal-engine-config-hooks/spec.md:30:- The hook's `usage` parameter is typed `TurnUsage`, exported from the package root, so its signature names it as the whole turn's total rather than one provider call's ([validated by: folds every provider round of a turn into one TurnUsage](../../src/orchestration/orchestratorHelpers.test.ts#L48)).
specs/hal-engine-config-hooks/spec.md:31:- Two provider rounds that both report usage sum field by field into the turn total ([validated by: sums each token field of two reported rounds](../../src/orchestration/orchestratorHelpers.test.ts#L32)).
specs/hal-engine-config-hooks/spec.md:32:- A round that reports nothing leaves the turn total unchanged ([validated by: keeps the total when a round reports nothing](../../src/orchestration/orchestratorHelpers.test.ts#L36)).
specs/hal-engine-config-hooks/spec.md:33:- The first round that reports usage starts the turn total ([validated by: starts the total from the first reported round](../../src/orchestration/orchestratorHelpers.test.ts#L40)).
specs/hal-engine-config-hooks/spec.md:34:- The turn total stays `undefined` while no round has reported usage ([validated by: stays undefined while no round has reported](../../src/orchestration/orchestratorHelpers.test.ts#L44)).

